export function build(THREE, p, ctx) {
  const g = new THREE.Group();
  const r = p.radius || 80;
  const geo = new THREE.CircleGeometry(r, 48);
  geo.rotateX(-Math.PI / 2);
  const tex = ctx.dataTexture(64, 64, (u, v) => {
    const n = 0.8 + 0.2 * ctx.noise2(u * 20, v * 20);
    const c = n * 255;
    return [c * 0.82, c * 0.86, c * 0.95];
  });
  const m = ctx.mat(p.color || '#aab0bd', { emissive: p.color || '#7f8798', emissiveIntensity: p.glow || 0.25 });
  m.map = tex;
  g.add(new THREE.Mesh(geo, m));
  // scattered small ash mounds
  const count = 120;
  const mg = new THREE.IcosahedronGeometry(0.3, 0);
  const im = new THREE.InstancedMesh(mg, ctx.mat('#c3c8d2', { emissive: '#8a90a0', emissiveIntensity: 0.2 }), count);
  const d = new THREE.Object3D();
  for (let i = 0; i < count; i++) {
    const a = ctx.range(0, Math.PI * 2), rr = Math.sqrt(ctx.rng()) * (r * 0.7);
    d.position.set(Math.cos(a) * rr, -0.08, Math.sin(a) * rr);
    d.scale.set(ctx.range(0.5, 2), ctx.range(0.2, 0.5), ctx.range(0.5, 2));
    d.rotation.y = ctx.range(0, 6);
    d.updateMatrix();
    im.setMatrixAt(i, d.matrix);
  }
  g.add(im);
  return g;
}

