export function build(THREE, p, ctx) {
  const g = new THREE.Group();
  const n = p.count || 300, R = p.radius || 90;
  const pos = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) {
    const a = ctx.range(0, 6.283), e = Math.asin(ctx.range(0.05, 1));
    pos[i * 3] = Math.cos(a) * Math.cos(e) * R;
    pos[i * 3 + 1] = Math.sin(e) * R;
    pos[i * 3 + 2] = Math.sin(a) * Math.cos(e) * R;
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  const m = new THREE.PointsMaterial({ color: p.color || '#cfd8ff', size: 2, sizeAttenuation: false, fog: false, transparent: true, opacity: 0.85 });
  g.add(new THREE.Points(geo, m));
  return g;
}

export function build(THREE, p, ctx) {
  const g = new THREE.Group();
  const n = p.perRow || 3, sp = p.spacing || 4, w = p.width || 6, h = p.height || 2.5;
  const lean = (p.lean || 5) * Math.PI / 180;
  const m = ctx.mat(p.color || '#14151c', { emissive: '#1a1d2e', emissiveIntensity: 0.15 });
  for (let row = 0; row < 2; row++) {
    for (let i = 0; i < n; i++) {
      const hh = h * ctx.range(0.93, 1.05);
      const geo = new THREE.CylinderGeometry(0.09, 0.14, hh, 5);
      geo.translate(0, hh / 2, 0);
      const post = new THREE.Mesh(geo, m);
      post.position.set((row - 0.5) * w + ctx.range(-0.15, 0.15), -0.1, -i * sp);
      post.rotation.x = -lean * ctx.range(0.7, 1.3);
      post.rotation.z = ctx.range(-0.04, 0.04);
      g.add(post);
      const cap = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.12, 0.22), m);
      cap.position.set(0, hh, 0);
      post.add(cap);
    }
  }
  return g;
}

