export function build(THREE, p, ctx) {
  const g = new THREE.Group();
  const r = p.radius || 160;
  const geo = new THREE.CircleGeometry(r, 48);
  geo.rotateX(-Math.PI / 2);
  const tex = ctx.dataTexture(64, 64, (u, v) => {
    const n = 0.85 + 0.15 * ctx.noise2(u * 20, v * 20);
    const c = n * 255;
    return [c * 0.82, c * 0.86, c * 0.95];
  });
  const m = ctx.mat(p.color || '#8f98ad', { emissive: '#6c7690', emissiveIntensity: p.glow || 0.3 });
  m.map = tex;
  g.add(new THREE.Mesh(geo, m));
  const sstep = (a, b, x) => { const t = Math.max(0, Math.min(1, (x - a) / (b - a))); return t * t * (3 - 2 * t); };
  const mkGlow = (rgb, size, opacity, x, z) => {
    const t = ctx.dataTexture(64, 64, (u, v) => {
      const d = Math.min(1, Math.hypot(u - 0.5, v - 0.5) * 2);
      const k = Math.pow(1 - d, 2) * sstep(1, 0.6, d) * 255;
      return [k * rgb[0], k * rgb[1], k * rgb[2]];
    });
    const mat = new THREE.MeshBasicMaterial({ map: t, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, opacity: opacity });
    const mesh = new THREE.Mesh(new THREE.PlaneGeometry(size, size), mat);
    mesh.rotation.x = -Math.PI / 2;
    mesh.position.set(x, 0.02, z);
    g.add(mesh);
  };
  mkGlow([0.6, 0.68, 1], 18, 0.45, 0, 0);
  mkGlow([1, 0.7, 0.28], 14, 0.08, 0, p.lanternZ === undefined ? -40 : p.lanternZ);
  const total = p.mounds || 700;
  const cols = ['#a9b1c4', '#7d869b'];
  const mg = new THREE.IcosahedronGeometry(0.3, 0);
  const d = new THREE.Object3D();
  for (let k = 0; k < 2; k++) {
    const count = Math.floor(total / 2);
    const im = new THREE.InstancedMesh(mg, ctx.mat(cols[k], { emissive: cols[k], emissiveIntensity: 0.2 }), count);
    for (let i = 0; i < count; i++) {
      const a = ctx.range(0, Math.PI * 2), rr = Math.sqrt(ctx.rng()) * (r * 0.7);
      d.position.set(Math.cos(a) * rr, -0.08, Math.sin(a) * rr);
      d.scale.set(ctx.range(0.5, 2.5), ctx.range(0.3, 0.9), ctx.range(0.5, 2.5));
      d.rotation.y = ctx.range(0, 6);
      d.updateMatrix();
      im.setMatrixAt(i, d.matrix);
    }
    g.add(im);
  }
  // long low ridges, off the walking path
  const rg = new THREE.IcosahedronGeometry(1, 1);
  const ridgeMat = ctx.mat('#9aa3b9', { emissive: '#6c7690', emissiveIntensity: 0.2 });
  const ridges = [[-28, -15, 0.3, 40, 0.2], [30, -45, -0.2, 50, 0.15]];
  ridges.forEach((q) => {
    const mesh = new THREE.Mesh(rg, ridgeMat);
    mesh.position.set(q[0], -0.05, q[1]);
    mesh.rotation.y = q[2];
    mesh.scale.set(2.5, 0.35, q[3] / 2);
    g.add(mesh);
  });
  return g;
}

export function build(THREE, p, ctx) {
  const g = new THREE.Group();
  const n = p.perRow || 3, sp = p.spacing || 4, w = p.width || 6, h = p.height || 2.5;
  const lean = (p.lean || 6) * Math.PI / 180;
  const m = ctx.mat('#ffffff', { emissive: '#3a3f5c', emissiveIntensity: 0.35 });
  m.vertexColors = true;
  const mound = ctx.mat('#a9b1c4', { emissive: '#6c7690', emissiveIntensity: 0.25 });
  const dark1 = new THREE.Color('#14151c'), dark2 = new THREE.Color('#23252f'), amber = new THREE.Color('#ffb347');
  for (let row = 0; row < 2; row++) {
    for (let i = 0; i < n; i++) {
      const hh = h * ctx.range(0.9, 1.08);
      const geo = new THREE.CylinderGeometry(0.09, 0.14, hh, 5);
      geo.translate(0, hh / 2, 0);
      const pos = geo.attributes.position, nor = geo.attributes.normal;
      const cols = new Float32Array(pos.count * 3);
      const c = new THREE.Color();
      for (let v = 0; v < pos.count; v++) {
        const band = Math.floor(pos.getY(v) / 0.35 + ctx.noise2(i * 3 + row, 0) * 2) % 2;
        c.copy(band ? dark1 : dark2);
        if (nor.getZ(v) < -0.3) c.lerp(amber, 0.15);
        cols[v * 3] = c.r; cols[v * 3 + 1] = c.g; cols[v * 3 + 2] = c.b;
      }
      geo.setAttribute('color', new THREE.BufferAttribute(cols, 3));
      const post = new THREE.Mesh(geo, m);
      const x = (row - 0.5) * w + ctx.range(-0.15, 0.15), z = -i * sp;
      post.position.set(x, -0.1, z);
      post.rotation.x = -lean * ctx.range(0.5, 1.5);
      post.rotation.z = ctx.range(-0.04, 0.04);
      g.add(post);
      const cap = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.12, 0.22), m);
      cap.position.set(0, hh, 0);
      post.add(cap);
      const mo = new THREE.Mesh(new THREE.IcosahedronGeometry(0.5, 0), mound);
      mo.position.set(x, -0.12, z);
      mo.scale.set(1, 0.3, 1);
      mo.rotation.y = ctx.range(0, 6);
      g.add(mo);
    }
  }
  return g;
}

export function build(THREE, p, ctx) {
  const g = new THREE.Group();
  const nf = p.flecks || 150, np = p.pebbles || 14;
  const z0 = p.zNear === undefined ? -2 : p.zNear, z1 = p.zFar === undefined ? -42 : p.zFar, hw = p.halfWidth || 6;
  const d = new THREE.Object3D();
  const fm = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(0.5, 0), ctx.mat('#dfe6ff', { emissive: '#dfe6ff', emissiveIntensity: 0.8 }), nf);
  for (let i = 0; i < nf; i++) {
    const t = ctx.rng();
    d.position.set(ctx.range(-hw, hw) * (0.5 + ctx.rng()), ctx.range(0.03, 1.5), z0 + (z1 - z0) * t);
    const s = ctx.range(0.03, 0.06);
    d.scale.set(s, s, s);
    d.updateMatrix();
    fm.setMatrixAt(i, d.matrix);
  }
  g.add(fm);
  const pm = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(1, 0), ctx.mat('#4a5068'), np);
  for (let i = 0; i < np; i++) {
    const t = Math.pow(ctx.rng(), 1.6);
    const side = ctx.rng() < 0.5 ? -1 : 1;
    d.position.set(side * ctx.range(1, hw + 2), 0.02, z0 + (z1 - z0) * t);
    const s = ctx.range(0.15, 0.3);
    d.scale.set(s, s * 0.6, s * ctx.range(0.8, 1.2));
    d.rotation.y = ctx.range(0, 6);
    d.updateMatrix();
    pm.setMatrixAt(i, d.matrix);
  }
  g.add(pm);
  return g;
}

