export function build(THREE, p, ctx) {
  const g = new THREE.Group();
  const R = p.radius || 0.75, H = p.height || 0.8;
  const stone = ctx.mat(p.color || '#6f768a', { emissive: '#2a3048', emissiveIntensity: 0.25 });
  const dark = ctx.mat('#4a5068', { emissive: '#2a3048', emissiveIntensity: 0.2 });
  const n = 10;
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2;
    const w = 2 * R * Math.sin(Math.PI / n) * 1.05;
    const h = H * ctx.range(0.85, 1.08);
    const b = new THREE.Mesh(new THREE.BoxGeometry(w, h, 0.32), ctx.rng() < 0.5 ? stone : dark);
    b.position.set(Math.cos(a) * R, h / 2 - 0.02, Math.sin(a) * R);
    b.rotation.y = -a + Math.PI / 2 + ctx.range(-0.05, 0.05);
    b.rotation.z = ctx.range(-0.03, 0.03);
    g.add(b);
  }
  const hole = new THREE.Mesh(new THREE.CircleGeometry(R * 0.85, 12), new THREE.MeshBasicMaterial({ color: '#010103' }));
  hole.rotation.x = -Math.PI / 2;
  hole.position.y = H * 0.7;
  g.add(hole);
  const rim = new THREE.Mesh(new THREE.TorusGeometry(R, 0.07, 4, 10), ctx.mat('#dfe6ff', { emissive: '#a9b1c4', emissiveIntensity: 0.45 }));
  rim.rotation.x = Math.PI / 2;
  rim.position.y = H + 0.02;
  rim.scale.set(1, 1, 0.5);
  g.add(rim);
  const mound = new THREE.Mesh(new THREE.IcosahedronGeometry(1, 0), ctx.mat('#a9b1c4', { emissive: '#6c7690', emissiveIntensity: 0.25 }));
  mound.scale.set(R * 1.7, 0.15, R * 1.7);
  mound.position.y = -0.05;
  g.add(mound);
  return g;
}

